mapper.select:
SELECT m.id, m.user_id, u.nickname AS user_nickname, u.avatar AS user_avatar, m.content, m.images AS images_json, m.related_type, m.related_id, m.audit_status, m.useful_count, m.comment_count, m.status, m.created_at FROM moment m JOIN user u ON m.user_id = u.id WHERE m.audit_status = 'approved' AND m.status = 0
AND m.related_type = 'dish' AND m.related_id = #{dishId}
AND m.related_type = 'stall' AND m.related_id = #{stallId}
AND m.related_type = 'stall' AND m.related_id IN (SELECT id FROM stall WHERE canteen_id = #{canteenId})
ORDER BY m.created_at DESC

SELECT m.id, m.user_id, u.nickname AS user_nickname, u.avatar AS user_avatar, m.content, m.images AS images_json, m.related_type, m.related_id, m.audit_status, m.reject_reason, m.useful_count, m.comment_count, m.status, m.created_at FROM moment m JOIN user u ON m.user_id = u.id WHERE m.user_id = #{userId}
AND m.audit_status = #{auditStatus}
ORDER BY m.created_at DESC
